assignments.value:
={{ 
(() => {
  const analysis = $('Set Plant Analysis Data').item.json.analysis;
  const activePlant = $('Build Image Context').item.json.active_plant || {};
  const language = $('Build Image Context').item.json.preferred_language || 'en';
  const isSameActivePlant = analysis.context_match === 'same_active_plant';

const commonName = isSameActivePlant
  ? (activePlant.nickname || analysis.common_name || activePlant.common_name)
  : analysis.common_name;

  const scientificName = isSameActivePlant
    ? (activePlant.scientific_name || analysis.scientific_name)
    : analysis.scientific_name;

  const labels = language === 'ja'
    ? {
        plant: '植物',
        health: '健康状態',
        symptoms: '確認できた症状',
        causes: '考えられる原因',
        advice: 'お手入れのアドバイス',
        confidence: '識別信頼度',
        continue: 'この植物について気になることがあれば、そのままLINEで質問してください。'
      }
    : {
        plant: 'Plant',
        health: 'Health Status',
        symptoms: 'Visible Symptoms',
        causes: 'Possible Causes',
        advice: 'Care Advice',
        confidence: 'Identification Confidence',
        continue: 'If you have any questions about this plant, just ask me here on LINE.'
      };

  return `🌱 PlantCare AI

【${labels.plant}】
${commonName}
${scientificName}

【${labels.health}】
${analysis.health_status}

【${labels.symptoms}】
${analysis.visible_symptoms.map(v => `・${v}`).join('\n')}

【${labels.causes}】
${analysis.possible_causes.map(v => `・${v}`).join('\n')}

【${labels.advice}】
${analysis.care_advice.map(v => `・${v}`).join('\n')}

${labels.confidence}：${analysis.confidence}%

${analysis.needs_another_photo
  ? `📷 ${analysis.photo_request_reason}`
  : labels.continue}`;
})()
}}

value.plant_id:
={{ $('Route by Image Context').item.json.analysis.context_match === 'same_active_plant'
  ? $('Build Image Context').item.json.active_plant.plant_id
  : 'plant_' + $('LINE Webhook Trigger').item.json.body.events[0].source.userId + '_' + $('Set Plant Analysis Data').item.json.analysis.scientific_name.toLowerCase().replace(/[^a-z0-9]+/g, '_')
}}

values.content:
={{ 
`Latest user message:
${$json.user_message}

Preferred language:
${$json.preferred_language || 'Not set'}

Active plant:
${JSON.stringify($json.plant_context)}

Recent plant observations:
${JSON.stringify($json.observation_history)}

Recent conversation history:
${JSON.stringify($json.conversation_history)}

Respond directly to the user's latest message.`
}}

parameters.jsonBody:
={{ JSON.stringify({
  replyToken: $('LINE Webhook Trigger').item.json.body.events[0].replyToken,
  messages: [
    {
      type: 'text',
      text: $('Set Chat Response Data').item.json.reply_text
    }
  ]
}) }}

assignments.value:
={{
(() => {
  const analysis = $('Set Plant Analysis Data').item.json.analysis || {};
  const language = $('Build Image Context').item.json.preferred_language || 'en';

  if (language === 'ja') {
    return `🌱 PlantCare AI

この写真だけでは、現在登録されている植物と同じ植物か、新しい植物かを十分な確度で判断できませんでした。

${analysis.photo_request_reason
  ? `📷 ${analysis.photo_request_reason}`
  : `📷 植物全体と、葉・茎の形がはっきり分かる写真をもう1枚送ってください。`}

現在の植物の登録情報は変更していません。`;
  }

  return `🌱 PlantCare AI

I couldn't determine with enough confidence whether this is the same plant currently registered or a new plant.

${analysis.photo_request_reason
  ? `📷 ${analysis.photo_request_reason}`
  : `📷 Please send another photo showing the whole plant and a clear view of its leaves and stem.`}

Your current plant record has not been changed.`;
})()
}}
